$U = $HOME
$msPaths = @((Get-Content -Raw "$U/DEV/KeystoneOS/data/memory-index-paths.json" | ConvertFrom-Json).paths | ForEach-Object { (($_ -replace '\{HOME\}', $U) -replace '\{DEV\}', "$U/DEV") -replace '\{VAULT\}', "$U/SecondBrain" })
$existingPaths = @($msPaths | Where-Object { Test-Path $_ })
$mdCount = @($existingPaths | ForEach-Object { Get-ChildItem -LiteralPath $_ -Recurse -File -Filter *.md -ErrorAction SilentlyContinue }).Count
$why = "$($existingPaths.Count)/$($msPaths.Count) paths exist, $mdCount .md files scanned"
foreach ($r in @('Indexed 0 chunks.', 'Indexed 190 chunks.', 'RuntimeError: Failed to open the local Milvus Lite database.')) {
    $code = 0
    $flag = if ("$r" -notmatch '^Indexed \d+ chunks') { ' -> ERROR memsearch-index:unexpected-output' } else { '' }
    $note = if ("$r" -match '^Indexed 0 chunks') { 'no new content since last index' } else { '' }
    "INDEX full set: $r ($why" + $(if ($note) { "; $note" } else { '' }) + ", exit $code)$flag"
}

